class Solution:
    def longestRide(self, fares: List[int], budget: int) -> int:
        n, best = len(fares), 0
        for i in range(n):
            total, j = 0, i
            while j < n and total + fares[j] <= budget:
                total += fares[j]
                j += 1
            best = max(best, j - i)
        return best

