from bisect import bisect_right


class Solution:
    def longestRide(self, fares: List[int], budget: int) -> int:
        pre = [0]
        for f in fares:
            pre.append(pre[-1] + f)
        best = 0
        for i in range(len(fares)):
            j = bisect_right(pre, pre[i] + budget) - 1
            best = max(best, j - i)
        return best

