class Solution {
    public int longestRide(int[] fares, int budget) {
        int n = fares.length, best = 0;
        long[] pre = new long[n + 1];
        for (int i = 0; i < n; i++) pre[i + 1] = pre[i] + fares[i];
        for (int i = 0; i < n; i++) {
            long cap = pre[i] + budget;
            int lo = i, hi = n;
            while (lo < hi) {
                int mid = (lo + hi + 1) / 2;
                if (pre[mid] <= cap) lo = mid; else hi = mid - 1;
            }
            best = Math.max(best, lo - i);
        }
        return best;
    }
}

