int longestRide(int* fares, int faresSize, int budget) {
    int n = faresSize, best = 0;
    long long* pre = malloc((n + 1) * sizeof(long long));
    pre[0] = 0;
    for (int i = 0; i < n; i++) pre[i + 1] = pre[i] + fares[i];
    for (int i = 0; i < n; i++) {
        long long cap = pre[i] + budget;
        int lo = i, hi = n;
        while (lo < hi) {
            int mid = (lo + hi + 1) / 2;
            if (pre[mid] <= cap) lo = mid; else hi = mid - 1;
        }
        if (lo - i > best) best = lo - i;
    }
    free(pre);
    return best;
}

